mkdirSync(backupDir, { recursive: true });
cpSync(join(root, 'src'), join(backupDir, 'src'), { recursive: true });
cpSync(join(root, 'package.json'), join(backupDir, 'package.json'));

console.log('2/4 Instalujem kompletny konzistentny zdrojovy kod v0.9.0...');
for (const [relativePath, compressed] of Object.entries(payload)) {
  const destination = join(root, relativePath);
  mkdirSync(dirname(destination), { recursive: true });
  const content = gunzipSync(Buffer.from(compressed, 'base64'));
  writeFileSync(destination, content);
}

